import{z as A,x as o,o as i,c as m,q as r,j as s,D as t,d as a,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"掩模版与场域极限","description":"","frontmatter":{"title":"掩模版与场域极限","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-field-limit.md","filePath":"litho/reticle-field-limit.md","lastUpdated":1791063341000}'),d={name:"litho/reticle-field-limit.md"};function h(p,E,c,D,C,F){const l=o("Mermaid");return i(),m("div",null,[E[2]||(E[2]=r('<h1 id="掩模版与场域极限" tabindex="-1">掩模版与场域极限 <a class="header-anchor" href="#掩模版与场域极限" aria-label="Permalink to &quot;掩模版与场域极限&quot;">​</a></h1><div class="epigraph"><p>光罩就那么大一块玻璃：26×33mm 的场域是整条产线的宪法——芯片放不下就切割，切割不了就拼接，拼接不了就限制你的设计。</p><footer>—— 据 ASML TWINSCAN NXT/EUV 场域规格；SEMI 标准光罩尺寸 6 英寸</footer></div><p><a href="/litho/dummy-fill-density">虚拟填充与密度规则</a>管版图的均匀性，本课管版图的<strong>疆界</strong>：投影透镜的像方场域固定为 26×33mm，所有芯片必须住进去。缺口是<strong>场域约束</strong>——reticle field limit 如何从物理常数变成设计规则，以及切缝（stitch）与场域拼接的代价。本课不做光罩写版的次序优化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投影系统的像差校正只对一个圆内的像质有保证，现代 EUV/浸没式透镜把这个圆切成 26×33mm 矩形用足。设计侧的麻烦：Die 尺寸逼近或超过场域怎么办（GPU/SoC 常 600mm² 以上，而场域 858mm² 一颗都放不满两颗）；跨场域的大电路怎么办（数据通路、时钟树被切缝劈开）。缺口：把「玻璃的大小」翻译成设计与分割的语言。</p><p><span class="marginnote">术语翻译：reticle field（场域）= 投影一次成像的最大面积，4:3 legacy 与 EUV 的 26×33mm；stitch（切缝）= 把超过场域的图形拆到两次曝光、晶圆上对齐拼接；stitch error = 拼接处的套刻与 CD 失配。</span></p><p><span class="marginnote">数字实例：场域 26×33=858mm²。300mm 晶圆产出的 die 数受「场域内能摆几颗」硬约束：600mm² 的 GPU 一场一颗、浪费 258mm²；320mm² 的可一场两颗。同设计面积翻倍到 640mm² 后一颗一场，wafer 利用率骤降——这是「单 die 变 dual chiplet」的产能数学。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计响应分三档。<strong>缩 die 进场</strong>：最省事，规模天花板即场域面积；<strong>chiplet 拆分</strong>：把大设计切成多 die 各自进场，代价是互连（D2D 接口功耗/带宽）与封装；<strong>切缝拼接</strong>：同一 die 跨场域两次曝光在晶圆上拼接——只对「可切」的电路成立（横向数据流可切、SRAM 阵列与模拟电路不可切），且切缝处的套刻失配要设计容错（冗余线、可修复逻辑）。光罩侧的对应操作：field stitching 的两条 reticle 各含半幅图形 + 对准标记。</p>',9)),(i(),s(n,null,{default:t(()=>[B(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Die%20%E9%9D%A2%E7%A7%AF%20vs%20%E5%9C%BA%E5%9F%9F%20858mm%C2%B2%22%5D%20--%3E%20B%7B%22%E6%94%BE%E5%BE%97%E4%B8%8B%3F%22%7D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%5B%22%E5%8D%95%E6%AC%A1%E6%9B%9D%E5%85%89%E6%88%90%E5%9E%8B%22%5D%0A%20%20B%20--%3E%7C%22%E7%95%A5%E8%B6%85%22%7C%20D%5B%22%E7%BC%A9%20die%20%E6%88%96%E6%94%B9%E5%88%86%E5%9D%97%22%5D%0A%20%20B%20--%3E%7C%22%E8%BF%9C%E8%B6%85%22%7C%20E%7B%22%E7%94%B5%E8%B7%AF%E5%8F%AF%E5%88%87%3F%22%7D%0A%20%20E%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E6%B5%81%E5%8F%AF%E5%88%87%22%7C%20F%5B%22stitch%20%E6%8B%BC%E6%8E%A5%20%2B%20%E5%86%97%E4%BD%99%E5%AE%B9%E9%94%99%22%5D%0A%20%20E%20--%3E%7C%22%E9%98%B5%E5%88%97%2F%E6%A8%A1%E6%8B%9F%22%7C%20G%5B%22chiplet%20%E6%8B%86%E5%88%86%E5%B0%81%E8%A3%85%E4%BA%92%E8%BF%9E%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：场域像「复印机的最大复印幅面」——A3 玻璃就那么大；大图纸要么缩印（缩小 die），要么拆成两张分别复印再对齐拼贴（chiplet），要么复印两次精确接缝（stitch）；接缝处再对齐也有毫米级误差，重要文字（SRAM）绝不能骑缝。")],-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"光学机制：透镜像差（场曲、像散、畸变）沿径向恶化，「可用矩形」是像质达标的内接区——扩大场域意味着更难的透镜设计与更贵的系统，26×33 是 EUV 反射镜组的工程平衡点。拼接机制：两次曝光的图形在晶圆上以套刻精度对齐（EUV ~2nm 级、浸没式 ~3-5nm），切缝误差表现为图形的 CD 突变与位置错动——设计侧用「缝区冗余」吸收：把不可精确的边界放在无关紧要的位置（如重复单元的间隙），配 eFuse 修复。产能机制：每片晶圆的曝光次数 = 场域数 + 缝合开销，多 die 单场（MD1）比单 die 多场便宜且快。",-1)),(i(),s(n,null,{default:t(()=>[B(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%9C%BA%E5%9F%9F%E4%B8%BA%E4%BD%95%E5%9B%BA%E5%AE%9A%3F%22%7D%20--%3E%20R%5B%22%E9%80%8F%E9%95%9C%E5%83%8F%E5%B7%AE%E6%B2%BF%E5%BE%84%E5%90%91%E6%81%B6%E5%8C%96%22%5D%0A%20%20R%20--%3E%20S%5B%22%E5%8F%AF%E7%94%A8%E7%9F%A9%E5%BD%A2%20%3D%20%E5%83%8F%E8%B4%A8%E5%86%85%E6%8E%A5%E5%8C%BA%22%5D%0A%20%20T%7B%22%E7%BC%9D%E4%B8%8A%E4%BB%80%E4%B9%88%E4%B8%8D%E8%83%BD%E6%94%BE%3F%22%7D%20--%3E%20U%5B%22SRAM%2F%E6%A8%A1%E6%8B%9F%2F%E6%97%B6%E9%92%9F%E6%A0%91%22%5D%0A%20%20U%20--%3E%20V%5B%22%E7%BC%9D%E5%8C%BA%E5%8F%AA%E7%95%99%E5%86%97%E4%BD%99%E4%B8%8E%E4%BF%AE%E5%A4%8D%E7%82%B9%22%5D%0A%20%20W%7B%22%E4%BA%A7%E8%83%BD%E8%B4%A6%E6%80%8E%E4%B9%88%E7%AE%97%3F%22%7D%20--%3E%20X%5B%22MD1%20%E5%A4%9A%20die%20%E4%B8%80%E5%9C%BA%E6%9C%80%E7%9C%81%22%5D%0A%20%20V%20--%3E%20Y%5B%22%E6%8B%BC%E6%8E%A5%20%3D%20%E7%B2%BE%E5%BA%A6%E6%8D%A2%E9%9D%A2%E7%A7%AF%22%5D%0A%20%20X%20--%3E%20Y%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">常见误区：以为 die 大小只受晶圆面积限制——wafer 有 706mm² 半径盘，场域只有 858mm² 矩形，两套几何各自卡脖子；另一误区是「stitch 是免费的」——它要求两次曝光、两次对准、缝区冗余设计，良率敏感电路绕行是常态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>High-NA EUV 的场域砍半（26×16.5mm）：单次成像面积小一半，成为 Intel/TSMC 引入 High-NA 时最大的流程重构项——0.55NA 的镜筒用更小的场域换更高的分辨率，chiplet 与 stitching 从「可选项」变「必答题」。设计侧的场域意识：physical design 工具的「reticle awareness」（虚场域规划、切缝规划）在 3nm 以下节点已是标准动作。与<a href="/litho/mix-and-match-overlay">混合匹配与套刻拼接</a>的接续：stitch 是同机同 reticle 拼接，mix-and-match 是不同光刻机接力同一层——两者共享「套刻是货币」的经济学。</p><p><span class="marginnote">直觉类比：High-NA 场域减半像「换了一台放大倍率更高的投影仪」——画面更精细，但幕布同宽下能投的画面变小；原来一幕放下的戏（单 die）现在要么拆成上下半场（chiplet），要么学会换幕衔接（stitch）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>26×33mm 是透镜像差内接的工程宪法，产量账从这里算起。</li><li>超场域三策：缩 die、chiplet 拆分、stitch 拼接，各有互连/套刻代价。</li><li>缝区只放冗余；High-NA 减半场域把拼接推向必答题。</li><li>出处：ASML NXE/EXE 场域规格书；SEMI P1 光罩标准；chiplet 经济性研究（Resetting the Canvas 等）。</li></ul>',6))])}const u=A(d,[["render",h]]);export{g as __pageData,u as default};
